content.text:
{
  "name": "原始数据写盘组件",
  "name_en": "Raw-to-Disk Writer",
  "manufacturer": "",
  "description": "非物理软件组件，用于在实验采集过程中异步将原始数据流写入磁盘文件，以尽量降低对 UDP 接收可靠性的影响。",
  "description_en": "A non-physical software component for asynchronously writing raw data streams to disk files during experimental acquisition, helping minimize impact on UDP reception reliability.",
  "actions": [
    {
      "action_name": "auto-open_file",
      "description": "创建并打开指定路径和文件名的原始数据文件，用于后续写入。",
      "description_en": "Create and open a raw data file at the specified path and filename for subsequent writing."
    },
    {
      "action_name": "auto-close",
      "description": "关闭当前正在写入的文件。",
      "description_en": "Close the file currently being written."
    },
    {
      "action_name": "auto-write",
      "description": "将提供的缓冲区原始数据写入当前文件。",
      "description_en": "Write the provided raw buffer data to the current file."
    }
  ],
  "tag_hints": [
    "raw data logging",
    "disk streaming",
    "asynchronous file writing",
    "UDP data acquisition",
    "experiment data capture"
  ]
}

